class Solution {
  public TreeNode inorderSuccessor(TreeNode root, TreeNode p) {
    TreeNode successor = null;
    for (TreeNode cur = root; cur != null; ) {
      if (cur.val > p.val) {
        successor = cur;
        cur = cur.left;
      } else cur = cur.right;
    }
    return successor;
  }
}
